import {
  Carousel as CarouselPrimitive,
  useCarousel,
  useCarouselContext,
} from '@ark-ui/solid/carousel';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, For, splitProps } from 'solid-js';
import { ChevronLeftIcon, ChevronRightIcon } from '@/lib/moduix/icons/ui/Icons';
import styles from './Carousel.module.css';

function CarouselRoot(props: ComponentProps<typeof CarouselPrimitive.Root>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.Root
      data-slot="carousel-root"
      class={clsx(styles.root, local.class)}
      {...others}
    />
  );
}

function CarouselRootProvider(props: ComponentProps<typeof CarouselPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.RootProvider
      data-slot="carousel-root-provider"
      class={clsx(styles.root, local.class)}
      {...others}
    />
  );
}

function CarouselControl(props: ComponentProps<typeof CarouselPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.Control
      data-slot="carousel-control"
      class={clsx(styles.control, local.class)}
      {...others}
    />
  );
}

function CarouselItemGroup(props: ComponentProps<typeof CarouselPrimitive.ItemGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.ItemGroup
      data-slot="carousel-item-group"
      class={clsx(styles.itemGroup, local.class)}
      {...others}
    />
  );
}

function CarouselItem(props: ComponentProps<typeof CarouselPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.Item
      data-slot="carousel-item"
      class={clsx(styles.item, local.class)}
      {...others}
    />
  );
}

function CarouselPrevTrigger(props: ComponentProps<typeof CarouselPrimitive.PrevTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <CarouselPrimitive.PrevTrigger
      asChild={local.asChild}
      data-slot="carousel-prev-trigger"
      class={clsx(styles.prevTrigger, local.class)}
      {...others}
    >
      {resolvedChildren() ?? (
        <span class={styles.defaultIcon}>
          <ChevronLeftIcon />
        </span>
      )}
    </CarouselPrimitive.PrevTrigger>
  );
}

function CarouselNextTrigger(props: ComponentProps<typeof CarouselPrimitive.NextTrigger>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <CarouselPrimitive.NextTrigger
      asChild={local.asChild}
      data-slot="carousel-next-trigger"
      class={clsx(styles.nextTrigger, local.class)}
      {...others}
    >
      {resolvedChildren() ?? (
        <span class={styles.defaultIcon}>
          <ChevronRightIcon />
        </span>
      )}
    </CarouselPrimitive.NextTrigger>
  );
}

function CarouselIndicatorGroup(props: ComponentProps<typeof CarouselPrimitive.IndicatorGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.IndicatorGroup
      data-slot="carousel-indicator-group"
      class={clsx(styles.indicatorGroup, local.class)}
      {...others}
    />
  );
}

function CarouselIndicator(props: ComponentProps<typeof CarouselPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.Indicator
      data-slot="carousel-indicator"
      class={clsx(styles.indicator, local.class)}
      {...others}
    />
  );
}

type CarouselIndicatorsProps = ComponentProps<typeof CarouselPrimitive.IndicatorGroup> & {
  indicatorClassName?: string;
};

function CarouselIndicators(props: CarouselIndicatorsProps) {
  const [local, others] = splitProps(props, ['class', 'children', 'indicatorClassName']);

  return (
    <CarouselPrimitive.Context>
      {(api) => (
        <CarouselIndicatorGroup class={local.class} {...others}>
          <For each={api().pageSnapPoints}>
            {(_, index) => <CarouselIndicator index={index()} class={local.indicatorClassName} />}
          </For>
        </CarouselIndicatorGroup>
      )}
    </CarouselPrimitive.Context>
  );
}

function CarouselAutoplayTrigger(props: ComponentProps<typeof CarouselPrimitive.AutoplayTrigger>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.AutoplayTrigger
      data-slot="carousel-autoplay-trigger"
      class={clsx(styles.autoplayTrigger, local.class)}
      {...others}
    />
  );
}

function CarouselAutoplayIndicator(
  props: ComponentProps<typeof CarouselPrimitive.AutoplayIndicator>,
) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.AutoplayIndicator
      data-slot="carousel-autoplay-indicator"
      class={clsx(styles.autoplayIndicator, local.class)}
      {...others}
    />
  );
}

function CarouselProgressText(props: ComponentProps<typeof CarouselPrimitive.ProgressText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <CarouselPrimitive.ProgressText
      data-slot="carousel-progress-text"
      class={clsx(styles.progressText, local.class)}
      {...others}
    />
  );
}

const Carousel = Object.assign(CarouselRoot, {
  Root: CarouselRoot,
  RootProvider: CarouselRootProvider,
  Context: CarouselPrimitive.Context,
  Control: CarouselControl,
  ItemGroup: CarouselItemGroup,
  Item: CarouselItem,
  PrevTrigger: CarouselPrevTrigger,
  NextTrigger: CarouselNextTrigger,
  IndicatorGroup: CarouselIndicatorGroup,
  Indicator: CarouselIndicator,
  Indicators: CarouselIndicators,
  AutoplayTrigger: CarouselAutoplayTrigger,
  AutoplayIndicator: CarouselAutoplayIndicator,
  ProgressText: CarouselProgressText,
});

export { Carousel, useCarousel, useCarouselContext };

@layer moduix.components {
  .root {
    display: flex;
    flex-direction: column;
    gap: var(--moduix-carousel-gap, var(--moduix-spacing-3));
    min-width: 0;
    width: 100%;
  }

  .root[data-orientation='vertical'] {
    align-items: stretch;
    flex-direction: row;
    height: var(--moduix-carousel-height, 24rem);
  }

  .control {
    display: flex;
    align-items: center;
    gap: var(--moduix-carousel-gap, var(--moduix-spacing-3));
    min-width: 0;
  }

  .control[data-orientation='vertical'] {
    flex-direction: column;
    justify-content: space-between;
  }

  .itemGroup {
    display: flex;
    flex: 1 1 auto;
    min-width: 0;
    min-height: 0;
    overscroll-behavior-x: contain;
    overscroll-behavior-y: auto;
    border-radius: var(--moduix-carousel-track-radius, var(--moduix-radius-xl));
    outline: 0;
    scrollbar-width: none;
    scroll-behavior: smooth;

    &::-webkit-scrollbar {
      display: none;
    }

    &:focus-visible {
      outline: var(
          --moduix-carousel-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
        solid var(--moduix-carousel-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(
        --moduix-carousel-focus-ring-offset,
        var(--moduix-focus-ring-inset-offset)
      );
    }

    &[data-dragging] {
      cursor: grabbing;
      user-select: none;
    }
  }

  .itemGroup[data-orientation='vertical'] {
    height: 100%;
    overscroll-behavior-x: auto;
    overscroll-behavior-y: contain;
  }

  .item {
    box-sizing: border-box;
    min-width: 0;
    min-height: 0;
  }

  .prevTrigger,
  .nextTrigger,
  .autoplayTrigger {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    width: var(--moduix-carousel-control-size, var(--moduix-size-md));
    height: var(--moduix-carousel-control-size, var(--moduix-size-md));
    border: var(--moduix-border-width-sm) solid
      var(
        --moduix-carousel-control-border-color,
        color-mix(in oklab, var(--moduix-color-border) 88%, black 12%)
      );
    border-radius: var(--moduix-radius-full);
    background-color: var(
      --moduix-carousel-control-bg,
      color-mix(in oklab, var(--moduix-color-background) 92%, var(--moduix-color-card) 8%)
    );
    box-shadow: var(--moduix-carousel-control-shadow, var(--moduix-shadow-sm));
    color: var(--moduix-carousel-control-color, var(--moduix-color-foreground));
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-fast),
      border-color var(--moduix-transition-fast),
      color var(--moduix-transition-fast),
      box-shadow var(--moduix-transition-fast),
      transform var(--moduix-transition-fast);

    & svg {
      width: var(--moduix-carousel-control-icon-size, var(--moduix-spacing-4));
      height: var(--moduix-carousel-control-icon-size, var(--moduix-spacing-4));
    }

    &:not(:disabled, [data-disabled]):hover {
      border-color: var(
        --moduix-carousel-control-border-color-hover,
        color-mix(in oklab, var(--moduix-color-border) 50%, var(--moduix-color-foreground) 50%)
      );
      background-color: var(--moduix-carousel-control-bg-hover, var(--moduix-color-accent));
      box-shadow: var(--moduix-carousel-control-shadow-hover, var(--moduix-shadow-md));
      color: var(--moduix-carousel-control-color-hover, var(--moduix-color-accent-foreground));
    }

    &:focus-visible {
      outline: var(
          --moduix-carousel-focus-ring-width,
          var(--moduix-focus-ring-width, var(--moduix-border-width-md))
        )
        solid var(--moduix-carousel-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-carousel-focus-ring-offset, var(--moduix-focus-ring-offset));
    }

    &:is(:disabled, [data-disabled]) {
      cursor: not-allowed;
      opacity: var(--moduix-opacity-disabled);
    }

    &[data-pressed] {
      border-color: var(
        --moduix-carousel-control-border-color-hover,
        color-mix(in oklab, var(--moduix-color-border) 50%, var(--moduix-color-foreground) 50%)
      );
      background-color: var(--moduix-carousel-control-bg-hover, var(--moduix-color-accent));
      color: var(--moduix-carousel-control-color-hover, var(--moduix-color-accent-foreground));
    }
  }

  .defaultIcon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .root[data-orientation='vertical'] {
    .defaultIcon {
      & svg {
        transform: rotate(90deg);
      }
    }
  }

  .root[data-orientation='horizontal'][dir='rtl'] {
    .defaultIcon {
      & svg {
        transform: rotate(180deg);
      }
    }
  }

  .indicatorGroup {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-carousel-indicator-gap, var(--moduix-spacing-2));
  }

  .indicatorGroup[data-orientation='vertical'] {
    flex-direction: column;
  }

  .indicator {
    width: var(--moduix-carousel-indicator-size, var(--moduix-spacing-2));
    height: var(--moduix-carousel-indicator-size, var(--moduix-spacing-2));
    padding: 0;
    border: 0;
    border-radius: var(--moduix-radius-full);
    background-color: var(
      --moduix-carousel-indicator-bg,
      color-mix(in oklab, var(--moduix-color-muted) 84%, var(--moduix-color-background) 16%)
    );
    cursor: pointer;
    opacity: 0.88;
    transition:
      width var(--moduix-transition-fast),
      height var(--moduix-transition-fast),
      background-color var(--moduix-transition-fast),
      opacity var(--moduix-transition-fast);

    &:not(:disabled, [data-disabled], [data-readonly], [data-current]):hover {
      background-color: var(
        --moduix-carousel-indicator-bg-hover,
        color-mix(in oklab, var(--moduix-color-muted) 56%, var(--moduix-color-foreground) 44%)
      );
    }

    &:focus-visible {
      outline: var(
          --moduix-carousel-focus-ring-width,
          var(--moduix-focus-ring-width, var(--moduix-border-width-md))
        )
        solid var(--moduix-carousel-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(--moduix-carousel-focus-ring-offset, var(--moduix-focus-ring-offset));
    }

    &[data-current] {
      width: calc(var(--moduix-carousel-indicator-size, var(--moduix-spacing-2)) * 3);
      background-color: var(--moduix-carousel-indicator-bg-current, var(--moduix-color-primary));
      opacity: 1;
    }

    &:is(:disabled, [data-disabled], [data-readonly]) {
      cursor: not-allowed;
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .indicator[data-orientation='vertical'][data-current] {
    width: var(--moduix-carousel-indicator-size, var(--moduix-spacing-2));
    height: calc(var(--moduix-carousel-indicator-size, var(--moduix-spacing-2)) * 3);
  }

  .autoplayTrigger {
    --_carousel-autoplay-trigger-min-width-fallback: calc(
      var(--moduix-size-md) + var(--moduix-spacing-3)
    );

    min-width: var(
      --moduix-carousel-autoplay-trigger-min-width,
      var(--_carousel-autoplay-trigger-min-width-fallback)
    );
  }

  .autoplayIndicator {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--moduix-carousel-autoplay-indicator-min-width, var(--moduix-spacing-4));
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-xs);
    text-transform: uppercase;
  }

  .progressText {
    color: var(--moduix-carousel-progress-text-color, var(--moduix-color-muted-foreground));
    direction: ltr;
    font-size: var(--moduix-carousel-progress-text-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-line-height-text-sm);
    font-variant-numeric: tabular-nums;
    unicode-bidi: isolate;
  }

  @media (prefers-reduced-motion: reduce) {
    .itemGroup {
      scroll-behavior: auto;
    }

    .prevTrigger,
    .nextTrigger,
    .autoplayTrigger,
    .indicator {
      transition: none;
    }
  }

  @media (forced-colors: active) {
    .indicator {
      background-color: ButtonText;
    }

    .indicator[data-current] {
      background-color: Highlight;
    }
  }
}
